    if targets:
        t, _ = nearest(targets, me)
        return step_toward(me, t)

    if neutral:
        t, _ = nearest(neutral, me)
        return step_toward(me, t)

    # Gentle exploration / fallback.
    explore = g(observation, "explore", None)
    if isinstance(explore, (list, tuple)):
        p = as_xy(explore)
        if p is not None:
            return step_toward(me, p)

    turn = g(observation, "turn", 0)
